// The engine bindings are JVM code generated by uniffi; they call the Rust library through JNA,
// which ships as an AAR on Android and a JAR on the desktop. One shared source directory
// (src/jvmShared) holds the app and is compiled into both the Android and desktop targets, each
// with its own JNA artifact, instead of an intermediate source set that would need one JNA for
// both. Generated bindings land in build/engine/kotlin (scripts/build-engine.sh).
val engineKotlin = rootProject.layout.projectDirectory.dir("build/engine/kotlin")

// Build identity. Stable builds take the workspace version from the root Cargo.toml. A preview
// build passes -Pcw.channel=preview -Pcw.preview=N (and optionally -Pcw.version=1.6.0): it shows
// as 1.6.0-preview.N and its installer version sits just below 1.6.0 (1.5.900N), so each
// preview upgrades the last and the final release upgrades every preview.
val cargoVersion = rootProject.file("../Cargo.toml").readLines()
    .first { it.startsWith("version = ") }.substringAfter('"').substringBefore('"')
val buildChannel = (findProperty("cw.channel") as String?) ?: "stable"
val previewNumber = (findProperty("cw.preview") as String?)?.toInt() ?: 0
val baseVersion = (findProperty("cw.version") as String?) ?: cargoVersion
val displayVersion = if (buildChannel == "preview") "$baseVersion-preview.$previewNumber" else baseVersion
val installerVersion = if (buildChannel == "preview") {
    val (major, minor, _) = baseVersion.split('.').map(String::toInt)
    "$major.${minor - 1}.${9_000 + previewNumber}"
} else {
    baseVersion
}
val buildInfoDir = layout.buildDirectory.dir("generated/buildinfo")
buildInfoDir.get().asFile.resolve("BuildInfo.kt").apply {
    parentFile.mkdirs()
    writeText(
        """
        |package net.lakesidegames.corporatewarfare
        |
        |/** Generated by shared/build.gradle.kts: which version and update channel this build is. */
        |object BuildInfo {
        |    const val VERSION = "$displayVersion"
        |    const val CHANNEL = "$buildChannel"
        |}
        |""".trimMargin(),
    )
}

kotlin {
    androidTarget {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        }
    }
    jvm("desktop") {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        }
    }

    sourceSets {
        val shared = listOf("src/jvmShared/kotlin", engineKotlin.asFile.path, buildInfoDir.get().asFile.path)
        androidMain {
            kotlin.srcDirs(shared)
            dependencies {
                implementation(compose.runtime)
                implementation(compose.foundation)
                implementation(compose.material3)
                implementation(compose.ui)
                implementation("${libs.jna.get()}@aar")
                implementation(libs.kotlinx.serialization.json)
            }
        }
        val desktopMain by getting {
            kotlin.srcDirs(shared)
            // JNA loads the engine from the classpath under its platform folder.
            resources.srcDir(rootProject.layout.projectDirectory.dir("build/engine/desktop"))
            dependencies {
                implementation(compose.runtime)
                implementation(compose.foundation)
                implementation(compose.material3)
                implementation(compose.ui)
                implementation(libs.jna)
                implementation(libs.kotlinx.serialization.json)
                // Skia's native renderer for the OS building the package (each OS packages its own).
                implementation(compose.desktop.currentOs)
            }
        }
        val desktopTest by getting {
            dependencies {
                implementation(kotlin("test"))
            }
        }
    }
}

android {
    namespace = "net.lakesidegames.corporatewarfare.shared"
    // The world map, shared with the iPhone app (copied by scripts/build-engine.sh).
    sourceSets["main"].resources.srcDir(rootProject.layout.projectDirectory.dir("build/engine/resources"))
    compileSdk = libs.versions.compileSdk.get().toInt()
    defaultConfig {
        minSdk = libs.versions.minSdk.get().toInt()
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

// Windows and Linux (and, unsigned, macOS) desktop builds of the same app.
compose.desktop {
    application {
        mainClass = "net.lakesidegames.corporatewarfare.MainKt"
        // The release build (createReleaseDistributable, packageReleaseMsi, packageReleaseDeb) runs ProGuard
        // to drop the Compose, Material and Kotlin classes the game never calls. Names are not obfuscated
        // (so crash reports stay readable) and code is not rewritten, only removed. The keep rules for
        // the engine bindings, JNA and Skia are in desktop-rules.pro.
        buildTypes.release.proguard {
            isEnabled.set(true)
            obfuscate.set(false)
            optimize.set(false)
            configurationFiles.from(project.file("desktop-rules.pro"))
        }
        nativeDistributions {
            targetFormats(
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Msi,
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Deb,
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Dmg,
            )
            packageName = "Corporate Warfare"
            // Only the Java modules the game uses go into the bundled runtime (find them with
            // :shared:suggestRuntimeModules): drawing and windows, the management beans the startup
            // timeline reads, logging, the HTTPS the updater and telemetry use (certificate name checks
            // need java.naming, elliptic curves need jdk.crypto.ec), and the unsafe access Skiko needs.
            modules("java.desktop", "java.instrument", "java.logging", "java.management", "java.naming", "jdk.crypto.ec", "jdk.unsupported")
            packageVersion = installerVersion
            vendor = "Lakeside Games"
            description = "Corporate Warfare: an economic strategy game"
            copyright = "Lakeside Games"
            linux {
                packageName = "corporate-warfare"
                iconFile.set(project.file("icons/corporate-warfare.png"))
            }
            windows {
                iconFile.set(project.file("icons/corporate-warfare.ico"))
                menuGroup = "Corporate Warfare"
                upgradeUuid = "5b6f6b2e-3c1d-4b8e-9f1a-0c7d2e4a9b31"
                // Start menu entry, desktop shortcut, and a choice of install folder.
                menu = true
                shortcut = true
                dirChooser = true
            }
        }
    }
}

// The Windows installer uses our copy of jpackage's WiX template (packaging/windows/main.wxs), which
// closes a running game on install and uninstall. Compose gives jpackage its own resource folder,
// empties it at the start of the task and passes it last, so neither a template placed beforehand
// nor an extra --resource-dir reaches jpackage. Instead, once Compose has built the MSI, this puts
// the template in that folder and runs jpackage again with Compose's own saved arguments, so every
// other installer setting stays exactly as Compose made it. That rerun reads Compose's working
// folder, which compose.preserve.working.dir in gradle.properties keeps.
// A failing test says why in the CI log (the assertion message), not only which line failed.
tasks.withType<Test>().configureEach {
    testLogging {
        events("failed")
        exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
        showCauses = true
    }
}

tasks.withType<org.jetbrains.compose.desktop.application.tasks.AbstractJPackageTask>().configureEach {
    if (targetFormat != org.jetbrains.compose.desktop.application.dsl.TargetFormat.Msi) return@configureEach
    val template = project.file("packaging/windows")
    val composeResources = project.layout.buildDirectory.dir("compose/tmp/resources")
    val argsFile = project.layout.buildDirectory.file("compose/tmp/$name.args.txt")
    val jdk = javaHome
    val wixDir = wixToolsetDir
    val output = destinationDir
    inputs.dir(template)
    doLast {
        val args = argsFile.get().asFile
        check(args.isFile) { "jpackage arguments not found at $args; the Compose plugin changed, see shared/build.gradle.kts" }
        template.copyRecursively(composeResources.get().asFile, overwrite = true)
        output.get().asFile.listFiles { file -> file.extension == "msi" }?.forEach { it.delete() }
        val process = ProcessBuilder(File(jdk.get(), "bin/jpackage.exe").path, "@${args.path}", "--verbose").redirectErrorStream(true)
        wixDir.orNull?.asFile?.let { wix ->
            val env = process.environment()
            val key = env.keys.firstOrNull { it.equals("PATH", ignoreCase = true) } ?: "PATH"
            env[key] = wix.path + File.pathSeparator + env[key].orEmpty()
        }
        val run = process.start()
        val log = run.inputStream.bufferedReader().readText()
        val code = run.waitFor()
        logger.lifecycle(log)
        check(code == 0) { "jpackage with packaging/windows/main.wxs failed with exit code $code; arguments:\n${args.readText()}" }
    }
}

// The branded Windows setup program (packaging/windows/setup.iss, Inno Setup 6) wraps the same
// app image Compose builds for the MSI. `:shared:packageWindowsSetup` builds the image, then the
// setup program, into build/compose/binaries/main-release/setup/CorporateWarfare-<version>-setup.exe.
// Windows only; CI installs Inno Setup when the runner lacks it.
val windowsHost = System.getProperty("os.name").lowercase().contains("win")
tasks.register<Exec>("packageWindowsSetup") {
    group = "distribution"
    description = "Builds CorporateWarfare-<version>-setup.exe with Inno Setup (Windows only)."
    dependsOn("createReleaseDistributable")
    onlyIf { windowsHost }
    val packaging = project.file("packaging/windows")
    val image = layout.buildDirectory.dir("compose/binaries/main-release/app/Corporate Warfare")
    val out = layout.buildDirectory.dir("compose/binaries/main-release/setup")
    inputs.dir(packaging)
    inputs.dir(image)
    outputs.dir(out)
    commandLine(
        "powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", File(packaging, "build-setup.ps1").path,
        "-DisplayVersion", displayVersion,
        "-NumericVersion", installerVersion,
        "-AppImage", image.get().asFile.path,
        "-OutDir", out.get().asFile.path,
    )
}

// Compose draws over a native panel only with interop blending on (Direct3D and Metal); the direct-map tests check it.
// The window tests need a display: on a Linux runner without one (no DISPLAY), AWT must stay headless so every other
// desktop test still runs and the direct-map tests skip themselves.
tasks.withType<Test>().configureEach {
    systemProperty("compose.interop.blending", "true")
    val linux = System.getProperty("os.name").lowercase().contains("linux")
    if (!linux || System.getenv("DISPLAY") != null) systemProperty("java.awt.headless", "false")
}
